import java.sql.*;

public class JdbcDemo {
    public static void main(String[] args) {
        String url = "jdbc:postgresql://localhost:5432/mydb";
        String user = "admin";
        String pass = "secret";

        // try-with-resources auto-closes Connection, PreparedStatement, ResultSet
        try (Connection conn = DriverManager.getConnection(url, user, pass)) {
            // PreparedStatement prevents SQL injection via parameterized queries
            String sql = "SELECT id, name, email FROM users WHERE age > ?";
            try (PreparedStatement ps = conn.prepareStatement(sql)) {
                ps.setInt(1, 18);  // bind the first (and only) parameter

                try (ResultSet rs = ps.executeQuery()) {
                    while (rs.next()) {
                        int id = rs.getInt("id");
                        String name = rs.getString("name");
                        String email = rs.getString("email");
                        System.out.printf("User %d: %s <%s>%n", id, name, email);
                    }
                }
            }
        } catch (SQLException e) {
            // SQLException is checked -- must catch or declare
            System.err.println("Database error: " + e.getMessage());
            e.printStackTrace();
        }
    }
}

```java
// JDBC: program against interfaces; the driver implements them
String url = "jdbc:mysql://localhost:3306/shop";
try (Connection con = DriverManager.getConnection(url, "user", "pass");
     PreparedStatement ps = con.prepareStatement("SELECT name FROM users WHERE id = ?")) {
    ps.setInt(1, 42);
    try (ResultSet rs = ps.executeQuery()) {
        if (rs.next()) System.out.println(rs.getString("name"));
    }
}
// Connection, PreparedStatement, ResultSet are JDBC interfaces;
// the MySQL driver provides the concrete classes.
```

```java
DataSource ds = ...;                              // entry point (pooled)
try (Connection con = ds.getConnection();        // Connection
     PreparedStatement ps =                        // PreparedStatement
         con.prepareStatement("SELECT id, name FROM users WHERE active = ?")) {
    ps.setBoolean(1, true);
    try (ResultSet rs = ps.executeQuery()) {       // ResultSet
        while (rs.next()) {
            System.out.println(rs.getInt("id") + ": " + rs.getString("name"));
        }
    }
} catch (SQLException e) {                          // SQLException
    throw new RuntimeException("query failed", e);
}
```

