String sql = "SELECT id, name FROM users WHERE city = ?";
try (Connection con = dataSource.getConnection();              // 1
     PreparedStatement ps = con.prepareStatement(sql)) {        // 2
    ps.setString(1, "Pune");                                    // 3 bind
    try (ResultSet rs = ps.executeQuery()) {                    // 3 execute (SELECT)
        while (rs.next()) {                                     // 4
            System.out.println(rs.getInt("id") + ": " + rs.getString("name"));
        }
    }
}                                                              // 5 auto-close

// for INSERT/UPDATE/DELETE use executeUpdate (returns row count):
